#include "tigersheets/session.hpp"
#include "tigersheets/pivot.hpp"
#include "../src/prepared_native_transaction.hpp"
#include <algorithm>
#include <chrono>
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
using Clock=std::chrono::steady_clock;
double ms(Clock::time_point start){return std::chrono::duration<double,std::milli>(Clock::now()-start).count();}
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
Json source(int records){Json cells=Json::array();cells.get_ref<Json::array_t&>().reserve((records+1)*10);for(int col=1;col<=10;++col)cells.push_back({{"row",1},{"col",col},{"input",col==1?"Region":col==2?"Revenue":"Field"+std::to_string(col)}});for(int row=2;row<=records+1;++row)for(int col=1;col<=10;++col)cells.push_back({{"row",row},{"col",col},{"input",std::to_string(col==1?row%10:col)}});return {{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Source"},{"cells",std::move(cells)}}})}};}
Json report(Json& book,int records){book["sheets"].push_back({{"id","r"},{"name","Report"},{"cells",Json::array()}});const Json definition={{"id","p"},{"name","RevenueReport"},{"source",{{"sheet","s"},{"row1",1},{"col1",1},{"row2",records+1},{"col2",10}}},{"rows",Json::array({{{"field","Region"}}})},{"columns",Json::array()},{"filters",Json::array()},{"values",Json::array({{{"field","Revenue"},{"aggregate","sum"},{"name","Revenue"}}})},{"output",{{"sheet","r"},{"row1",1},{"col1",1}}}};const auto generated=generatePivot(book,{{"revision",0},{"status","ok"},{"values",Json::array()}},definition);Json operations=Json::array({{{"type","add_sheet"},{"id","r"},{"name","Report"}}});for(auto& operation:pivotOperations(book,generated))operations.push_back(std::move(operation));book["sheets"].erase(book["sheets"].begin()+1);return operations;}
void allocationAndAtomicHistory(){auto book=source(2000);const auto operations=report(book,2000);WorkbookSession live(book);const auto original=live.snapshot();const auto* allocation=&book.at("sheets")[0].at("cells")[1000];std::string error;auto prepared=WorkbookSession::prepareTransaction(std::move(book),operations,&error);require(prepared&&prepared->changed(),"native report preparation succeeds");require(&prepared->snapshot().at("sheets")[0].at("cells")[1000]==allocation,"native report preparation must retain the owned source allocation without cloning");require(live.snapshot()==original&&!live.canUndo(),"preparation leaves live workbook and history unchanged");if(!live.commitPrepared(0,*prepared,&error))throw std::runtime_error(error);require(live.snapshotView().at("sheets")[0]==original.at("sheets")[0],"publication preserves source inputs and metadata exactly");require(live.snapshotView().at("pivots")[0].at("layout").at("grandTotals")[0].at("value")==4000,"native report publishes correct totals");require(live.historyBytes()<1000000,"native report history excludes immutable source cells");const auto delta=live.takeRecoveryDelta();require(delta.size()==1&&delta[0].at("patch")==true,"new worksheet publishes one structural recovery delta");auto recovered=original.patch(delta[0].at("changes"));recovered["revision"]=delta[0].at("revision");require(recovered==live.snapshotView(),"recovery delta replays the exact native publication");const auto* publishedAllocation=&live.snapshotView().at("sheets")[0].at("cells")[1000];require(live.undo()&&live.snapshotView().at("sheets")==original.at("sheets")&&!live.snapshotView().contains("pivots")&&!live.canUndo(),"one undo removes only the new report and worksheet");require(&live.snapshotView().at("sheets")[0].at("cells")[1000]==publishedAllocation,"native report undo must retain the untouched source allocation");require(live.redo()&&live.snapshotView().at("pivots")[0].at("layout").at("grandTotals")[0].at("value")==4000,"redo restores native report cache and cells atomically");require(&live.snapshotView().at("sheets")[0].at("cells")[1000]==publishedAllocation,"native report redo must retain the untouched source allocation");}
void equivalent(const Json& book,const Json& operations){
 WorkbookSession generic(book),live(book);std::string error;const auto revision=book.at("revision").get<std::uint64_t>();const bool applied=generic.apply(revision,operations,&error);if(!applied)throw std::runtime_error("generic characterization batch: "+error);auto prepared=WorkbookSession::prepareTransaction(book,operations,&error);require(prepared&&prepared->snapshot()==generic.snapshotView(),"native preparation matches the complete generic result");require(live.commitPrepared(revision,*prepared,&error),"native characterization publishes");require(live.snapshotView()==generic.snapshotView()&&live.lastChange()==generic.lastChange()&&live.historyBytes()==generic.historyBytes(),"native publication retains exact history and change notification");require(live.takeRecoveryDelta()==generic.takeRecoveryDelta(),"native publication retains the exact recovery delta");if(generic.canUndo()){require(live.undo()&&generic.undo()&&live.snapshotView()==generic.snapshotView(),"native undo matches generic undo");require(live.redo()&&generic.redo()&&live.snapshotView()==generic.snapshotView(),"native redo matches generic redo");}else require(!live.canUndo(),"native no-op has no history");
}
Json refresh(const Json& book,Json definition){const auto generated=generatePivot(book,{{"revision",book.at("revision")},{"status","ok"},{"values",Json::array()}},definition);return pivotOperations(book,generated);}
void preservedGuards(){
 auto empty=source(30);const auto initial=report(empty,30);WorkbookSession created(empty);require(created.apply(0,initial),"prepare initial report characterization");auto book=created.snapshot();
 // Filter refresh keeps an existing destination's custom style and unowned data.
 book["sheets"][1]["cells"][2]["style"]={{"fill","#123456"},{"note","keep"}};book["sheets"][1]["cells"].push_back({{"row",100},{"col",10},{"input","outside"}});auto filtered=book.at("pivots")[0];filtered["filters"]=Json::array({{{"field","Region"},{"all",false},{"items",Json::array({{{"type","number"},{"value",2}}})}}});equivalent(book,refresh(book,filtered));
 equivalent(book,refresh(book,book.at("pivots")[0]));
 // Report moves must retain formula rewriting on every worksheet.
 book["sheets"][0]["cells"].push_back({{"row",40},{"col",1},{"input","=Report!B2"}});auto moved=book.at("pivots")[0];moved["output"]["row1"]=5;moved["output"]["col1"]=4;equivalent(book,refresh(book,moved));
 // The old behavior removes owner cells globally, including malformed strays.
 auto stray=book;stray["sheets"][0]["cells"][15]["pivotOwner"]="p";equivalent(stray,refresh(stray,filtered));
 // Explicit static conversion may remove only legacy metadata in its prefix.
 auto conversion=empty;conversion["pivots"]=Json::array({{{"id","old"},{"staticSummary",true}}});auto converted=initial;converted.insert(converted.begin()+1,Json{{"type","set_metadata"},{"key","pivots"},{"value",Json::array()}});equivalent(conversion,converted);
 auto invalid=[&](Json input,Json operations,const char* expected){WorkbookSession live(input),generic(input);const auto before=live.snapshot();std::string error;require(!generic.apply(input.at("revision"),operations,&error)&&error.find(expected)!=std::string::npos,"generic path refuses unsafe native batch");require(!WorkbookSession::prepareTransaction(std::move(input),operations,&error)&&error.find(expected)!=std::string::npos,"native preparation preserves the same safety refusal");require(live.snapshot()==before&&!live.canUndo()&&live.takeRecoveryDelta().empty(),"failed preparation leaves live cells, history and recovery unchanged");};
 auto occupied=empty;occupied["sheets"].push_back({{"id","r"},{"name","Report"},{"cells",Json::array({{{"row",1},{"col",1},{"input","occupied"}}})}});invalid(occupied,Json::array({initial.back()}),"occupied");
 auto badStyle=initial;badStyle.back()["cells"][0]["style"]={{"fontSize",0}};invalid(empty,badStyle,"fontSize");
 auto badCache=initial;badCache.back()["definition"]["cache"]["sourceRevision"]=10;invalid(empty,badCache,"revision conflict");
 auto badNames=initial;badNames[0]["name"]="Source";invalid(empty,badNames,"Duplicate worksheet");
 auto malformedOwner=empty;malformedOwner["sheets"][0]["cells"][15]["pivotOwner"]=42;invalid(malformedOwner,initial,"type must be string");
 auto badMetadata=initial;badMetadata.insert(badMetadata.begin()+1,Json{{"type","set_metadata"},{"key","pivots"},{"value",book.at("pivots")}});invalid(empty,badMetadata,"typed report operations");
 auto invalidSource=empty;invalidSource["sheets"][0]["cells"][20]["input"]=3;std::string error;require(!WorkbookSession::prepareTransaction(std::move(invalidSource),initial,&error)&&error.find("input must be text")!=std::string::npos,"source validation still precedes native preparation");
 auto stale=WorkbookSession::prepareTransaction(empty,initial);WorkbookSession live(empty);require(live.apply(0,Json::array({{{"type","set_cell"},{"sheet","s"},{"row",2},{"col",2},{"input","live"}}})),"advance live revision");const auto before=live.snapshot();require(!live.commitPrepared(1,*stale,&error)&&live.snapshot()==before,"native publication rejects a stale captured revision");
}
void restorationOnFailure(){auto book=source(30);const auto operations=report(book,30);const auto original=book;const auto* allocation=&book["sheets"][0]["cells"][20];bool detached=false;try{NativePreparationProjection projected(book,operations);detached=book["sheets"][0]["cells"].empty();throw std::runtime_error("simulated transaction failure");}catch(const std::runtime_error&){require(book==original&&&book["sheets"][0]["cells"][20]==allocation,"unwinding restores every original source allocation");}require(detached,"bounded native guard detaches the immutable source");}
void historyProjectionGuards(){
 auto book=source(30);auto operations=report(book,30);operations.insert(operations.begin()+1,Json{{"type","add_sheet"},{"id","extra"},{"name","Extra"}});equivalent(book,operations);
 WorkbookSession created(book);require(created.apply(0,operations),"create history projection fixture");book=created.snapshot();const auto original=book;const auto* allocation=&book["sheets"][0]["cells"][20];
 const Json invalid=Json::array({{{"op","remove"},{"path","/sheets/1"}},{{"op","remove"},{"path","/pivots"}},{{"op","remove"},{"path","/missing"}}});bool detached=false,failed=false;
 try{NativePreparationProjection projected(book,invalid,NativePreparationProjection::HistoryPatch{});detached=book["sheets"][0]["cells"].empty();book=book.patch(invalid);}catch(const Json::exception&){failed=true;}
 require(detached&&failed&&book==original&&&book["sheets"][0]["cells"][20]==allocation,"a failed history patch restores every untouched source allocation and complete workbook");
 const Json interior=Json::array({{{"op","add"},{"path","/sheets/-"},{"value",{{"id","new"},{"name","New"},{"cells",Json::array()}}}},{{"op","replace"},{"path","/sheets/0/cells/20/input"},{"value","changed"}}});
 {NativePreparationProjection projected(book,interior,NativePreparationProjection::HistoryPatch{});require(!book["sheets"][0]["cells"].empty(),"history interior-cell edits retain the general patch path");}
 equivalent(book,Json::array({{{"type","add_sheet"},{"id","new"},{"name","New"}},{{"type","set_cell"},{"sheet","s"},{"row",2},{"col",2},{"input","77"}}}));
}
void canonicalGuards(){
 auto unsorted=source(30);auto& cells=unsorted["sheets"][0]["cells"];std::reverse(cells.begin(),cells.end());WorkbookSession sorted(std::move(unsorted));require(sorted.snapshotView()["sheets"][0]["cells"]==source(30)["sheets"][0]["cells"],"untrusted unsorted cells are still fully canonicalized");
 auto refused=[](Json book,const char* expected){try{WorkbookSession invalid(std::move(book));}catch(const std::exception& failure){require(std::string(failure.what()).find(expected)!=std::string::npos,"untrusted canonicalization reports its validation error");return;}throw std::runtime_error("untrusted invalid cell escaped canonicalization");};
 auto invalid=source(30);invalid["sheets"][0]["cells"].push_back(invalid["sheets"][0]["cells"][0]);refused(std::move(invalid),"Duplicate cell");
 invalid=source(30);invalid["sheets"][0]["cells"][15]["row"]=1048577;refused(std::move(invalid),"out of bounds");
 invalid=source(30);invalid["sheets"][0]["cells"][15]["input"]=3;refused(std::move(invalid),"input must be text");
 invalid=source(30);invalid["sheets"][0]["cells"][15]["style"]={{"fontSize",0}};refused(std::move(invalid),"fontSize");
}
void historyBenchmark(){auto book=source(100000);const auto operations=report(book,100000);WorkbookSession live(book);auto prepared=WorkbookSession::prepareTransaction(std::move(book),operations);require(prepared&&live.commitPrepared(0,*prepared),"publish capacity report before undo measurement");prepared.reset();const auto* allocation=&live.snapshotView()["sheets"][0]["cells"][1000];auto start=Clock::now();require(live.undo(),"capacity native report undo succeeds");Json metrics={{"sourceCells",1000000},{"undoMs",ms(start)},{"undoSourceAllocationRetained",&live.snapshotView()["sheets"][0]["cells"][1000]==allocation}};start=Clock::now();require(live.redo(),"capacity native report redo succeeds");metrics["redoMs"]=ms(start);metrics["redoSourceAllocationRetained"]=&live.snapshotView()["sheets"][0]["cells"][1000]==allocation;std::cout<<metrics.dump(2)<<'\n';require(metrics.at("undoSourceAllocationRetained")&&metrics.at("redoSourceAllocationRetained"),"native report undo and redo must retain the untouched million-cell source allocation");require(metrics.at("undoMs").get<double>()<100&&metrics.at("redoMs").get<double>()<100,"one-million-cell native undo and redo must each dispatch in under100ms on this host");}
void canonicalBenchmark(){auto book=source(100000);const auto start=Clock::now();WorkbookSession canonical(std::move(book));const auto elapsed=ms(start);std::cout<<Json{{"sourceCells",1000000},{"constructorCanonicalizationMs",elapsed}}.dump(2)<<'\n';require(elapsed<1000,"already ordered one-million-cell input must remain fully validated in under one second on this host");}
void benchmark(int records){Json metrics={{"records",records},{"sourceCells",records*10}};auto start=Clock::now();auto book=source(records);metrics["fixtureMs"]=ms(start);start=Clock::now();const auto operations=report(book,records);metrics["generationMs"]=ms(start);auto input=book;start=Clock::now();{WorkbookSession canonical(std::move(input));metrics["constructorCanonicalizationMs"]=ms(start);start=Clock::now();std::string error;if(!canonical.apply(0,operations,&error))throw std::runtime_error(error);metrics["genericApplyMs"]=ms(start);start=Clock::now();}metrics["genericRetirementMs"]=ms(start);input=std::move(book);const auto* allocation=&input.at("sheets")[0].at("cells")[1000];start=Clock::now();std::string error;auto prepared=WorkbookSession::prepareTransaction(std::move(input),operations,&error);metrics["factoryMs"]=ms(start);require(prepared&&prepared->changed(),"exact-capacity native preparation succeeds");metrics["sourceAllocationRetained"]=&prepared->snapshot().at("sheets")[0].at("cells")[1000]==allocation;std::cout<<metrics.dump(2)<<'\n';require(metrics.at("sourceAllocationRetained"),"native report preparation must retain the owned source allocation without cloning");}
int main(int argc,char** argv){try{if(argc>1){if(std::string(argv[1])=="canonical")canonicalBenchmark();else if(std::string(argv[1])=="history")historyBenchmark();else benchmark(std::stoi(argv[1]));}else{allocationAndAtomicHistory();preservedGuards();restorationOnFailure();historyProjectionGuards();canonicalGuards();std::cout<<"prepared native tests passed\n";}}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
